package au.aumanet.app;
import java.security.KeyPair;import java.util.concurrent.atomic.*;

/** Job-local readiness policy + actual pinned P256 cold-node boot protocol. No BIND ACK invented. */
public final class GatewayOwnerReadyTest {
 static int checks,tests;static void check(boolean value){checks++;if(!value)throw new AssertionError("Owner readiness check "+checks);}
 static final String RUN="4".repeat(32),NEXT="5".repeat(32);static final long WALL=1700000000000L;
 static void batches(){tests++;GatewayOwnerReady r=new GatewayOwnerReady();check(!r.ready(RUN,1000,WALL,()->true));check(!r.issued(RUN,1,2,1000,WALL/1000+30,()->true));check(!r.issued(RUN,1,1,1000,WALL/1000+30,()->true));check(!r.issued(RUN,2,2,1000,WALL/1000+30,()->false));check(!r.ready(RUN,1000,WALL,()->true));check(r.issued(RUN,2,2,1000,WALL/1000+30,()->true));check(r.ready(RUN,1000,WALL,()->true));check(!r.ready(NEXT,1000,WALL,()->true));check(!r.ready("",1000,WALL,()->true));check(!new GatewayOwnerReady().ready(RUN,1000,WALL,()->true));check(!r.ready(RUN,1000,WALL,()->false));}
 static void expiry(){tests++;GatewayOwnerReady r=new GatewayOwnerReady();check(r.issued(RUN,2,2,1000,WALL/1000+30,()->true));check(r.ready(RUN,14999,WALL+13999,()->true));check(!r.ready(RUN,15000,WALL+14000,()->true));check(!r.ready(RUN,999,WALL,()->true));check(!r.ready(RUN,31000,WALL,()->true));check(!r.ready(RUN,1000,0,()->true));check(!r.ready(RUN,1000,Long.MAX_VALUE,()->true));AtomicInteger gate=new AtomicInteger();check(!r.ready(RUN,1000,WALL,()->gate.incrementAndGet()==1));}
 static void publication(){tests++;GatewayOwnerReady r=new GatewayOwnerReady();check(r.issued(NEXT,2,2,2000,WALL/1000+31,()->true));check(!r.issued(RUN,2,2,1000,WALL/1000+30,()->true));check(r.ready(NEXT,2000,WALL+1000,()->true));AtomicInteger calls=new AtomicInteger();check(!r.issued(RUN,2,2,3000,WALL/1000+32,()->{if(calls.incrementAndGet()==1)return true;r.issued(NEXT,2,2,4000,WALL/1000+33,()->true);return false;}));check(r.ready(NEXT,4000,WALL+3000,()->true));}
 static void cold()throws Exception{tests++;KeyPair owner=GatewayBootTest.key(),node=GatewayBootTest.key();GatewayBootTest.Clock clock=new GatewayBootTest.Clock();AtomicBoolean current=new AtomicBoolean(true);GatewayBootRecovery proof=GatewayBootTest.node(owner,node,null);GatewayOwnerReady ready=new GatewayOwnerReady();GatewayBootCodec.Message q=proof.begin(GatewayBootTest.NONCE,clock,current::get);GatewayBootCodec.Message time=proof.receive(GatewayBootTest.signed(GatewayBootTest.proof(q,NEXT,0,0,null),node),clock,current::get);check(time!=null);check(proof.readyRun(clock,current::get).isEmpty());check(!ready.ready(proof.readyRun(clock,current::get),clock.elapsed,clock.wall,current::get));GatewayBootStore store=new GatewayBootStore(new GatewayIssuerTest.Storage());GatewayBootStore.Record record=store.prepare(GatewayBootTest.pin(node),time,"");proof.prepared(time,record,clock,current::get);clock.add(999);proof.receive(GatewayBootTest.signed(GatewayBootTest.ack(time),node),clock,current::get);check(proof.readyRun(clock,current::get).equals(NEXT));check(!ready.ready(proof.readyRun(clock,current::get),clock.elapsed,clock.wall,current::get));check(!ready.issued(NEXT,1,2,clock.elapsed,clock.wall/1000+30,current::get));check(!ready.ready(proof.readyRun(clock,current::get),clock.elapsed,clock.wall,current::get));check(ready.issued(NEXT,2,2,clock.elapsed,clock.wall/1000+30,current::get));check(ready.ready(proof.readyRun(clock,current::get),clock.elapsed,clock.wall,current::get));current.set(false);check(!ready.ready(NEXT,clock.elapsed,clock.wall,current::get));current.set(true);clock.add(GatewayBootRecovery.FRESH_MS);check(proof.readyRun(clock,current::get).isEmpty());check(!ready.ready(proof.readyRun(clock,current::get),clock.elapsed,clock.wall,current::get));}
 static void adapter()throws Exception{tests++;KeyPair owner=GatewayBootTest.key(),node=GatewayBootTest.key();SystemClock.now=1000;GatewayOwnerReadyHarness h=new GatewayOwnerReadyHarness();GatewayOwnerReadyHarness.Job job=new GatewayOwnerReadyHarness.Job();h.current=job;GatewayBootRecovery proof=GatewayBootTest.node(owner,node,null);GatewayOwnerReadyHarness.BootNode a=new GatewayOwnerReadyHarness.BootNode(proof);job.boots.add(a);check(!h.ownerReady(job));job.state="renewing";job.lastIssued=1;check(!h.ownerReady(job));GatewayBootCodec.Message q=proof.begin(GatewayBootTest.NONCE,GatewayOwnerReadyHarness.BOOT_CLOCK,()->true);proof.receive(GatewayBootTest.signed(GatewayBootTest.proof(q,RUN,2,System.currentTimeMillis()+12000,null),node),GatewayOwnerReadyHarness.BOOT_CLOCK,()->true);check(!h.ownerReady(job));long wall=System.currentTimeMillis();h.afterBatch(job,a,1,java.util.Arrays.asList(null,null),RUN,wall,()->true);check(!h.ownerReady(job));h.afterBatch(job,a,2,java.util.Arrays.asList(null,null),RUN,wall,()->false);check(!h.ownerReady(job));h.afterBatch(job,a,2,java.util.Arrays.asList(null,null),RUN,wall,()->true);check(h.ownerReady(job));h.allowed=false;check(!h.ownerReady(job));h.allowed=true;h.current=new GatewayOwnerReadyHarness.Job();check(!h.ownerReady(job));h.current=job;SystemClock.now+=GatewayBootRecovery.FRESH_MS;check(!h.ownerReady(job));}
 static void diagnostics(){tests++;GatewayOwnerReady r=new GatewayOwnerReady();GatewayOwnerReady.Diagnostic d=r.diagnostic("",1000,WALL,()->true);check(!d.ready&&!d.freshOwnerProof&&!d.completeOwnerBatch&&d.reason.equals("OWNER_PROOF_UNAVAILABLE"));d=r.diagnostic(RUN,1000,WALL,()->true);check(d.freshOwnerProof&&!d.completeOwnerBatch&&d.reason.equals("OWNER_BATCH_UNAVAILABLE"));check(r.issued(RUN,2,2,1000,WALL/1000+30,()->true));d=r.diagnostic(RUN,1000,WALL,()->true);check(d.ready&&d.completeOwnerBatch&&d.unexpiredOwnerBatch&&d.reason.equals("READY"));d=r.diagnostic(NEXT,1000,WALL,()->true);check(!d.ready&&d.reason.equals("OWNER_BATCH_RUN_CHANGED"));d=r.diagnostic(RUN,15000,WALL+14000,()->true);check(!d.ready&&!d.unexpiredOwnerBatch&&d.reason.equals("OWNER_BATCH_EXPIRED"));d=r.diagnostic(RUN,1000,WALL,()->false);check(!d.ready&&d.reason.equals("AUTHORITY_UNAVAILABLE"));}
 public static void main(String[] args)throws Exception{batches();expiry();publication();cold();adapter();diagnostics();System.out.println("{\"status\":\"passed\",\"testCount\":"+tests+",\"assertionCount\":"+checks+"}");}
}
